```js
// apiClient.js
const cache = new Map();
const TTL_MS = 5 * 60 * 1000; // 5 minutes

export async function fetchWeatherData(city) {
  const key = city.trim().toLowerCase();
  if (!key) throw new Error('Enter a city name');

  const cached = cache.get(key);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.data;
  }
  if (cached) cache.delete(key); // expired

  const url = new URL('https://api.openweathermap.org/data/2.5/weather');
  url.search = new URLSearchParams({
    q: city.trim(),
    units: 'metric',
    appid: import.meta.env?.VITE_OPENWEATHER_API_KEY ?? ''
  });

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Weather API error: ${response.status}`);
  }

  const data = await response.json();
  cache.set(key, { data, expiresAt: Date.now() + TTL_MS });
  return data;
}
```

This cache lasts only for the current page session; refreshing clears it. If you want cached results to survive refreshes, use `localStorage` with a timestamp and the same expiry check. Catch errors where you call `fetchWeatherData()` so they can be shown in your UI.

